<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">我的子域名</h1><p class="text-muted">配额 <?= h(count($subs)) ?> / <?= h($quota['subs']) ?>，每个子域名 <?= h($quota['records']) ?> 条记录。</p></div><?php if ($domains): ?><a class="btn btn-primary" href="<?= h(url_to('index/dns/register', ['domain_id' => $domains[0]['id']])) ?>">注册子域名</a><?php endif; ?></div><div class="mb-3"><?php foreach ($domains as $d): ?><a class="btn btn-sm btn-outline-primary me-2 mb-2" href="<?= h(url_to('index/dns/register', ['domain_id' => $d['id']])) ?>"><?= h($d['domain']) ?>（<?= (float)$d['price'] > 0 ? money($d['price']) : '免费' ?>）</a><?php endforeach; ?></div><div class="table-card table-responsive"><table class="table align-middle"><thead><tr><th>域名</th><th>状态</th><th>到期</th><th>记录数</th><th>操作</th></tr></thead><tbody><?php foreach ($subs as $s): ?><tr><td class="mono"><?= h($s['fqdn']) ?></td><td><?= status_badge($s['status'], 'subdomain') ?></td><td><?= $s['expire_time'] ? h(fmt_time($s['expire_time'])) : '永久' ?></td><td><?= h($s['record_count']) ?> / <?= h($quota['records']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= h(url_to('index/dns/records', ['id' => $s['id']])) ?>">解析</a> <a class="btn btn-sm btn-outline-secondary" href="<?= h(url_to('index/dns/renew', ['id' => $s['id']])) ?>">续期</a><form class="d-inline" method="post" action="<?= h(url_to('index/dns/release')) ?>" data-confirm="确定释放该子域名？"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($s['id']) ?>"><button class="btn btn-sm btn-outline-danger">释放</button></form></td></tr><?php endforeach; ?><?php if (!$subs): ?><tr><td colspan="5" class="empty">暂无子域名</td></tr><?php endif; ?></tbody></table></div><div class="card mt-4"><div class="card-body"><b>允许记录类型：</b><?= h(implode('、', $quota['types'])) ?>。线路与 Cloudflare 代理能力取决于会员等级、套餐及根域名配置。</div></div>
